int main() {
    char s[1001];
    fgets(s, sizeof(s), stdin);

    // Remove newline if present
    int len = strlen(s);
    if (len > 0 && s[len-1] == '\n') {
        s[len-1] = '\0';
        len--;
    }

    // Define keyboard layout
    // Row 0: 1234567890
    // Row 1: qwertyuiop
    // Row 2: asdfghjkl
    // Row 3: zxcvbnm

    // Create arrays to store row and column for each character
    int row[128], col[128];

    // Initialize with -1 for characters not on keyboard
    for (int i = 0; i < 128; i++) {
        row[i] = -1;
        col[i] = -1;
    }

    // Row 0: digits
    char row0[] = "1234567890";
    for (int i = 0; row0[i]; i++) {
        row[(int)row0[i]] = 0;
        col[(int)row0[i]] = i;
    }

    // Row 1: qwertyuiop
    char row1[] = "qwertyuiop";
    for (int i = 0; row1[i]; i++) {
        row[(int)row1[i]] = 1;
        col[(int)row1[i]] = i;
    }

    // Row 2: asdfghjkl
    char row2[] = "asdfghjkl";
    for (int i = 0; row2[i]; i++) {
        row[(int)row2[i]] = 2;
        col[(int)row2[i]] = i;
    }

    // Row 3: zxcvbnm
    char row3[] = "zxcvbnm";
    for (int i = 0; row3[i]; i++) {
        row[(int)row3[i]] = 3;
        col[(int)row3[i]] = i;
    }

    int total_presses = 0;
    int curr_row = 0, curr_col = 0;  // Start at '1'

    for (int i = 0; i < len; i++) {
        char c = s[i];

        // Convert uppercase to lowercase for keyboard lookup
        if (isupper(c)) {
            c = tolower(c);
        }

        if (row[(int)c] == -1) {
            continue;  // Skip characters not on keyboard
        }

        int target_row = row[(int)c];
        int target_col = col[(int)c];

        // Add Manhattan distance for navigation
        int moves = abs(target_row - curr_row) + abs(target_col - curr_col);
        total_presses += moves;

        // Add 1 for OK button press
        total_presses += 1;

        // Update current position
        curr_row = target_row;
        curr_col = target_col;
    }

    printf("%d\n", total_presses);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAXR 55
#define MAXC 55
#define INF 1000000000

typedef struct {
    int r, c;
} Cell;

typedef struct {
    int to;
    int cost;
} Edge;

static char grid[MAXR][MAXC + 5];
static int R, C;
static int n;                    // total cells = R*C

static int left_to[MAXR * MAXC];
static int right_to[MAXR * MAXC];
static int up_to[MAXR * MAXC];
static int down_to[MAXR * MAXC];

static int dist_all[MAXR * MAXC][MAXR * MAXC];

static inline int id(int r, int c) {
    return r * C + c;
}

static void build_moves() {
    for (int r = 0; r < R; r++) {
        for (int c = 0; c < C; c++) {
            int v = id(r, c);
            char ch = grid[r][c];

            int nc = c;
            while (nc - 1 >= 0 && grid[r][nc - 1] == ch) nc--;
            if (nc - 1 >= 0) left_to[v] = id(r, nc - 1);
            else left_to[v] = v;

            nc = c;
            while (nc + 1 < C && grid[r][nc + 1] == ch) nc++;
            if (nc + 1 < C) right_to[v] = id(r, nc + 1);
            else right_to[v] = v;

            int nr = r;
            while (nr - 1 >= 0 && grid[nr - 1][c] == ch) nr--;
            if (nr - 1 >= 0) up_to[v] = id(nr - 1, c);
            else up_to[v] = v;

            nr = r;
            while (nr + 1 < R && grid[nr + 1][c] == ch) nr++;
            if (nr + 1 < R) down_to[v] = id(nr + 1, c);
            else down_to[v] = v;
        }
    }
}

static void bfs_from(int s) {
    static int q[MAXR * MAXC];
    int head = 0, tail = 0;

    for (int i = 0; i < n; i++) dist_all[s][i] = INF;
    dist_all[s][s] = 0;
    q[tail++] = s;

    while (head < tail) {
        int v = q[head++];
        int d = dist_all[s][v];

        int nxts[4] = { left_to[v], right_to[v], up_to[v], down_to[v] };
        for (int k = 0; k < 4; k++) {
            int u = nxts[k];
            if (dist_all[s][u] > d + 1) {
                dist_all[s][u] = d + 1;
                q[tail++] = u;
            }
        }
    }
}

int main() {
    if (scanf("%d %d", &R, &C) != 2) return 0;
    for (int i = 0; i < R; i++) {
        scanf("%s", grid[i]);
    }

    char target[10005];
    scanf("%s", target);

    n = R * C;
    build_moves();

    for (int i = 0; i < n; i++) bfs_from(i);

    long long ans = 0;
    int cur = 0; // start at top-left

    for (int i = 0; target[i]; i++) {
        char need = target[i];
        int best = INF;

        for (int v = 0; v < n; v++) {
            int r = v / C, c = v % C;
            if (grid[r][c] == need && dist_all[cur][v] < best) {
                best = dist_all[cur][v];
            }
        }

        ans += best + 1; // movement + OK
        // after typing, cursor may be at any occurrence achieving best;
        // choose one minimizing future is unnecessary because distances are
        // computed to all equal cells and staying on any identical connected
        // block position is equivalent under the skip rule for repeated chars.
        // We can pick one best occurrence.
        for (int v = 0; v < n; v++) {
            int r = v / C, c = v % C;
            if (grid[r][c] == need && dist_all[cur][v] == best) {
                cur = v;
                break;
            }
        }
    }

    printf("%lld\n", ans);
    return 0;
}

import java.io.*;
