public class Solution {

    // Standard QWERTY keyboard layout
    private static final char[][] KEYBOARD = {
        {'q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p'},
        {'a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l'},
        {'z', 'x', 'c', 'v', 'b', 'n', 'm'}
    };

    // Map to store position of each character
    private static Map<Character, int[]> positionMap;

    static {
        positionMap = new HashMap<>();
        for (int i = 0; i < KEYBOARD.length; i++) {
            for (int j = 0; j < KEYBOARD[i].length; j++) {
                positionMap.put(KEYBOARD[i][j], new int[]{i, j});
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String input = br.readLine().trim().toLowerCase();

        int totalPresses = 0;
        int currentRow = 0;
        int currentCol = 0; // Start at 'q'

        for (char c : input.toCharArray()) {
            if (!positionMap.containsKey(c)) {
                continue; // Skip invalid characters
            }

            int[] targetPos = positionMap.get(c);
            int targetRow = targetPos[0];
            int targetCol = targetPos[1];

            // Calculate movements needed
            int rowDiff = Math.abs(targetRow - currentRow);
            int colDiff = Math.abs(targetCol - currentCol);

            // Add directional presses and the OK press
            totalPresses += rowDiff + colDiff + 1; // +1 for OK button

            // Update current position
            currentRow = targetRow;
            currentCol = targetCol;
        }

        System.out.println(totalPresses);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
            }
            if (c == '\r') {
                int d = read();
                if (d != '\n' && d != -1) ptr--;
            }
            if (c == -1 && sb.length() == 0) return null;
            return sb.toString();
        }

        String nextNonEmptyLine() throws IOException {
            String s;
            while ((s = nextLine()) != null) {
                if (!s.isEmpty()) return s;
            }
            return null;
        }
    }

    static int R, C;
    static char[][] grid;
    static int[][] id;
    static int n;
    static int[] rr, cc;
    static int[][] move = new int[4][];
    static int[][] dist;

    // 0=up,1=down,2=left,3=right
    static int buildNext(int r, int c, int dir) {
        char ch = grid[r][c];
        int nr = r, nc = c;
        if (dir == 0) {
            while (nr - 1 >= 0 && grid[nr - 1][nc] == ch) nr--;
            if (nr - 1 >= 0) nr--;
        } else if (dir == 1) {
            while (nr + 1 < R && grid[nr + 1][nc] == ch) nr++;
            if (nr + 1 < R) nr++;
        } else if (dir == 2) {
            while (nc - 1 >= 0 && grid[nr][nc - 1] == ch) nc--;
            if (nc - 1 >= 0) nc--;
        } else {
            while (nc + 1 < C && grid[nr][nc + 1] == ch) nc++;
            if (nc + 1 < C) nc++;
        }
        return id[nr][nc];
    }

    static void bfsAll() {
        dist = new int[n][n];
        for (int i = 0; i < n; i++) Arrays.fill(dist[i], -1);

        int[] q = new int[n];
        for (int s = 0; s < n; s++) {
            int head = 0, tail = 0;
            q[tail++] = s;
            dist[s][s] = 0;
            while (head < tail) {
                int u = q[head++];
                for (int d = 0; d < 4; d++) {
                    int v = move[d][u];
                    if (dist[s][v] == -1) {
                        dist[s][v] = dist[s][u] + 1;
                        q[tail++] = v;
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        String first = fs.nextNonEmptyLine();
        if (first == null) return;
        StringTokenizer st = new StringTokenizer(first);
        R = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());

        grid = new char[R][C];
        for (int i = 0; i < R; i++) {
            String line = fs.nextLine();
            while (line != null && line.length() < C) {
                String extra = fs.nextLine();
                if (extra == null) break;
                line += extra;
            }
            grid[i] = line.substring(0, C).toCharArray();
        }

        String target = fs.nextLine();
        if (target == null) target = "";

        id = new int[R][C];
        n = R * C;
        rr = new int[n];
        cc = new int[n];
        int idx = 0;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                id[i][j] = idx;
                rr[idx] = i;
                cc[idx] = j;
                idx++;
            }
        }

        for (int d = 0; d < 4; d++) move[d] = new int[n];
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                int cur = id[i][j];
                for (int d = 0; d < 4; d++) {
                    move[d][cur] = buildNext(i, j, d);
                }
            }
        }

        bfsAll();

        List<Integer>[] pos = new ArrayList[256];
        for (int i = 0; i < 256; i++) pos[i] = new ArrayList<>();
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                pos[grid[i][j]].add(id[i][j]);
            }
        }

        long[] prevCost = null;
        List<Integer> prevList = null;

        for (int t = 0; t < target.length(); t++) {
            char ch = target.charAt(t);
            List<Integer> curList = pos[ch];
            long[] curCost = new long[curList.size()];
            Arrays.fill(curCost, Long.MAX_VALUE / 4);

            if (t == 0) {
                int start = 0; // initial cursor at top-left
                for (int i = 0; i < curList.size(); i++) {
                    int v = curList.get(i);
                    curCost[i] = dist[start][v] + 1L; // move + OK
                }
            } else {
                for (int i = 0; i < curList.size(); i++) {
                    int v = curList.get(i);
                    long best = Long.MAX_VALUE / 4;
                    for (int j = 0; j < prevList.size(); j++) {
                        int u = prevList.get(j);
                        best = Math.min(best, prevCost[j] + dist[u][v] + 1L);
                    }
                    curCost[i] = best;
                }
            }

            prevList = curList;
            prevCost = curCost;
        }

        long ans;
        if (target.isEmpty()) {
            ans = 0;
        } else {
            ans = Long.MAX_VALUE;
            for (long v : prevCost) ans = Math.min(ans, v);
        }

        System.out.println(ans);
    }
}

import sys
from collections import deque

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    # Parse input:
    # R C
    # R lines of keyboard
    # target string
    first = data[0].split()
    if len(first) < 2:
        return
    R, C = map(int, first)
    grid = data[1:1 + R]
    target = data[1 + R] if 1 + R < len(data) else ""

    # Positions of each character
    pos = {}
    for i in range(R):
        for j in range(C):
            ch = grid[i][j]
            pos.setdefault(ch, []).append((i, j))

    # Precompute movement cost between every pair of cells:
    # moving with arrows through maximal runs of same character in a direction,
    # each arrow press costs 1, and OK costs handled separately.
    n = R * C
    dist = [[10**9] * n for _ in range(n)]

    def idx(x, y):
        return x * C + y

    # Build directed edges according to one arrow press
    adj = [[] for _ in range(n)]
    for x in range(R):
        for y in range(C):
            cur = grid[x][y]
            # up
            nx = x
            while nx - 1 >= 0 and grid[nx - 1][y] == cur:
                nx -= 1
            if nx - 1 >= 0:
                adj[idx(x, y)].append(idx(nx - 1, y))
            # down
            nx = x
            while nx + 1 < R and grid[nx + 1][y] == cur:
                nx += 1
            if nx + 1 < R:
                adj[idx(x, y)].append(idx(nx + 1, y))
            # left
            ny = y
            while ny - 1 >= 0 and grid[x][ny - 1] == cur:
                ny -= 1
            if ny - 1 >= 0:
                adj[idx(x, y)].append(idx(x, ny - 1))
            # right
            ny = y
            while ny + 1 < C and grid[x][ny + 1] == cur:
                ny += 1
            if ny + 1 < C:
                adj[idx(x, y)].append(idx(x, ny + 1))

    # BFS from each cell
    for s in range(n):
        dq = deque([s])
        dist[s][s] = 0
        while dq:
            u = dq.popleft()
            du = dist[s][u]
            for v in adj[u]:
                if dist[s][v] > du + 1:
                    dist[s][v] = du + 1
                    dq.append(v)

    # DP over possible positions of current typed character
    # Start at (0,0)
    start = idx(0, 0)

    if not target:
        print(0)
        return

    prev = {start: 0}
    for ch in target:
        if ch not in pos:
            print(-1)
            return
        cur_states = {}
        targets = [idx(x, y) for x, y in pos[ch]]
        for t in targets:
            best = 10**18
            for p, cost in prev.items():
                d = dist[p][t]
                if d < 10**9:
                    best = min(best, cost + d + 1)  # +1 for OK
            cur_states[t] = best
        prev = cur_states

    ans = min(prev.values())
    print(ans)

if __name__ == "__main__":
    solve()
